-- Exportación de entrenamiento desde nba_datos con la prioridad de fuentes (nba_oficial > sofascore > …) ya resuelta.
-- Uso (en el servidor): docker exec -i nba-db psql -U nba_admin -d nba_datos -f /tmp/exportar_entrenamiento.sql ; los CSV quedan en /tmp/.
-- Equivale a lo que lee nba.dato_a_las, pero sin corte temporal: son resultados finales de partidos ya jugados.

\copy (WITH pts AS (SELECT DISTINCT ON (d.partido_id, d.entidad_id) d.partido_id, d.entidad_id, d.valor FROM nba.dato d JOIN nba.metrica m ON m.metrica_id = d.metrica_id JOIN nba.fuente f ON f.fuente = d.fuente WHERE m.nombre = 'puntos' AND d.periodo = 0 AND d.fase = 'final' ORDER BY d.partido_id, d.entidad_id, f.prioridad, d.recibido_en DESC, d.dato_id DESC) SELECT e.fecha_juego_et AS fecha, e.temporada, e.entidad_id AS partido_id, tl.id_en_fuente AS local, tv.id_en_fuente AS visitante, pl.valor AS pts_local, pv.valor AS pts_visitante FROM nba.entidad e JOIN nba.entidad tl ON tl.entidad_id = (e.atributos->>'local')::bigint JOIN nba.entidad tv ON tv.entidad_id = (e.atributos->>'visitante')::bigint JOIN pts pl ON pl.partido_id = e.entidad_id AND pl.entidad_id = tl.entidad_id JOIN pts pv ON pv.partido_id = e.entidad_id AND pv.entidad_id = tv.entidad_id WHERE e.tipo = 'partido' AND e.canonica_id = e.entidad_id ORDER BY e.fecha_juego_et, e.entidad_id) TO '/tmp/s5_juegos.csv' WITH CSV HEADER

\copy (WITH r AS (SELECT DISTINCT ON (d.partido_id, d.entidad_id, d.metrica_id) d.partido_id, d.entidad_id, m.nombre, d.valor FROM nba.dato d JOIN nba.metrica m ON m.metrica_id = d.metrica_id JOIN nba.fuente f ON f.fuente = d.fuente WHERE d.fase = 'final' AND d.periodo = 0 AND m.nombre IN ('minutos', 'puntos', 'rebotes', 'asistencias', 'triples_anotados', 'mas_menos', 'titular', 'equipo_del_jugador') ORDER BY d.partido_id, d.entidad_id, d.metrica_id, f.prioridad, d.recibido_en DESC, d.dato_id DESC) SELECT r.partido_id, r.entidad_id AS jugador_id, max(CASE WHEN r.nombre = 'equipo_del_jugador' THEN r.valor END)::bigint AS equipo_id, max(CASE WHEN r.nombre = 'minutos' THEN r.valor END) AS minutos, max(CASE WHEN r.nombre = 'puntos' THEN r.valor END) AS puntos, max(CASE WHEN r.nombre = 'rebotes' THEN r.valor END) AS rebotes, max(CASE WHEN r.nombre = 'asistencias' THEN r.valor END) AS asistencias, max(CASE WHEN r.nombre = 'triples_anotados' THEN r.valor END) AS triples, max(CASE WHEN r.nombre = 'mas_menos' THEN r.valor END) AS mas_menos, max(CASE WHEN r.nombre = 'titular' THEN r.valor END) AS titular FROM r JOIN nba.entidad e ON e.entidad_id = r.partido_id AND e.canonica_id = e.entidad_id GROUP BY r.partido_id, r.entidad_id HAVING max(CASE WHEN r.nombre = 'equipo_del_jugador' THEN r.valor END) IS NOT NULL AND max(CASE WHEN r.nombre = 'minutos' THEN r.valor END) > 0) TO '/tmp/s5_caja.csv' WITH CSV HEADER

\copy (SELECT e.fecha_juego_et AS fecha, d.partido_id, d.entidad_id AS jugador_id, d.etiqueta AS estado, d.recibido_en AS hora_parte FROM nba.dato d JOIN nba.metrica m ON m.metrica_id = d.metrica_id JOIN nba.entidad e ON e.entidad_id = d.partido_id WHERE m.nombre = 'estado_disponibilidad' AND d.fuente = 'nba_oficial' AND d.etiqueta IS NOT NULL ORDER BY d.recibido_en) TO '/tmp/s5_estados.csv' WITH CSV HEADER

\copy (SELECT entidad_id, canonica_id, fuente, id_en_fuente FROM nba.entidad WHERE tipo = 'jugador') TO '/tmp/s5_jugadores.csv' WITH CSV HEADER

\copy (SELECT entidad_id, canonica_id, fuente, id_en_fuente FROM nba.entidad WHERE tipo = 'partido') TO '/tmp/s5_partidos.csv' WITH CSV HEADER

\copy (SELECT entidad_id, id_en_fuente FROM nba.entidad WHERE tipo = 'equipo') TO '/tmp/s5_equipos.csv' WITH CSV HEADER
